// Specialized Logic
//------------------------------------------------------------------------------

//------------------------------------------------------------------------------
// Memory rom: 16384-words x 32-bit (the picture program fills the 64 KB; sonata_romlinux has 9135, the BIOS)
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [31:0] rom[0:16383];
initial begin
	$readmemh("gen_soc_rom.init", rom);
end
reg [31:0] rom_dat0;
always @(posedge sys_clk) begin
	rom_dat0 <= rom[basesoc_basesoc_adr];
end
assign basesoc_basesoc_dat_r = rom_dat0;


//------------------------------------------------------------------------------
// Memory sram: 1536-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: Sync | Mode: Write-First | Write-Granularity: 8
reg [31:0] sram[0:1535];
initial begin
	$readmemh("gen_soc_sram.init", sram);
end
reg [10:0] sram_adr0;
always @(posedge sys_clk) begin : mem_write_block
	integer we_index;
	for(we_index = 0; we_index < 4; we_index=we_index+1)
		if (basesoc_ram_we[we_index])
			sram[basesoc_ram_adr][we_index*8 +: 8] <= basesoc_ram_dat_w[we_index*8 +: 8];
	sram_adr0 <= basesoc_ram_adr;
end
assign basesoc_ram_dat_r = sram[sram_adr0];


//------------------------------------------------------------------------------
// Memory mem: 43-words x 8-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [7:0] mem[0:42];
initial begin
	$readmemh("gen_soc_mem.init", mem);
end
reg [7:0] mem_dat0;
always @(posedge sys_clk) begin
	mem_dat0 <= mem[csr_bankarray_adr];
end
assign csr_bankarray_dat_r = mem_dat0;


//------------------------------------------------------------------------------
// Memory storage: 16-words x 10-bit
//------------------------------------------------------------------------------
// Port 0 | Read: ----  | Write: Sync | Mode: Read-First 
// Port 1 | Read: Sync  | Write: ---- | 
reg [9:0] storage[0:15];
reg [9:0] storage_dat1;
always @(posedge sys_clk) begin
	if (basesoc_uart_core_tx_fifo_wrport_we)
		storage[basesoc_uart_core_tx_fifo_wrport_adr] <= basesoc_uart_core_tx_fifo_wrport_dat_w;
end
always @(posedge sys_clk) begin
	if (basesoc_uart_core_tx_fifo_rdport_re) begin
		storage_dat1 <= storage[basesoc_uart_core_tx_fifo_rdport_adr];
	end
end
assign basesoc_uart_core_tx_fifo_rdport_dat_r = storage_dat1;


//------------------------------------------------------------------------------
// Memory storage_1: 16-words x 10-bit
//------------------------------------------------------------------------------
// Port 0 | Read: ----  | Write: Sync | Mode: Read-First 
// Port 1 | Read: Sync  | Write: ---- | 
reg [9:0] storage_1[0:15];
reg [9:0] storage_1_dat1;
always @(posedge sys_clk) begin
	if (basesoc_uart_core_rx_fifo_wrport_we)
		storage_1[basesoc_uart_core_rx_fifo_wrport_adr] <= basesoc_uart_core_rx_fifo_wrport_dat_w;
end
always @(posedge sys_clk) begin
	if (basesoc_uart_core_rx_fifo_rdport_re) begin
		storage_1_dat1 <= storage_1[basesoc_uart_core_rx_fifo_rdport_adr];
	end
end
assign basesoc_uart_core_rx_fifo_rdport_dat_r = storage_1_dat1;


